#include <stdio.h>
#include <string.h>
int main() {
    char num[100005]; int k; if (scanf("%s %d", num, &k) != 2) return 0;
    char stack[100005]; int top = 0;
    int len = strlen(num);
    for (int i = 0; i < len; i++) {
        char d = num[i];
        while (top > 0 && k > 0 && stack[top-1] > d) { top--; k--; }
        stack[top++] = d;
    }
    top -= k; if (top < 0) top = 0;
    int start = 0;
    while (start < top && stack[start] == '0') start++;
    if (start == top) puts("0");
    else {
        stack[top] = '\0';
        puts(stack + start);
    }
    return 0;
}

