        string stack = "";
        for (char d : num) {
            while (!stack.empty() && k > 0 && stack.back() > d) { stack.pop_back(); k--; }
            stack.push_back(d);
        }
        while (k > 0 && !stack.empty()) { stack.pop_back(); k--; }
        size_t start = stack.find_first_not_of('0');
        if (start == string::npos) cout << "0\n";
        else cout << stack.substr(start) << "\n";
    }
    return 0;
}

