import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String num = sc.next(); int k = sc.nextInt();
            StringBuilder stack = new StringBuilder();
            for (char d : num.toCharArray()) {
                while (stack.length() > 0 && k > 0 && stack.charAt(stack.length() - 1) > d) {
                    stack.deleteCharAt(stack.length() - 1); k--;
                }
                stack.append(d);
            }
            while (k > 0 && stack.length() > 0) {
                stack.deleteCharAt(stack.length() - 1); k--;
            }
            String res = stack.toString().replaceFirst("^0+(?!$)", "");
            System.out.println(res.isEmpty() ? "0" : res);
        }
    }
}

